#!/usr/bin/env python3
# Generated by runa via A2A Mesh delegation
"""
PG replica slot auto-heal
-------------------------
A meglévő slot-monitorozás kiegészítése auto-create lépéssel:
  - runa_replica / nova_replica slotok automatikus (re)létrehozása, ha hiányoznak
  - WAL-validáció: ellenőrzi, hogy a slotok nem ragadtak-e (restart_lsn nem stagnál)
  - ha a slot inaktív / nem létezik, maga gyógyítja, nem csak riaszt

Futtatható a repó gyökeréből:
    python scripts/pg_replica_slot_autoheal.py

Env változók (opcionális):
    PG_HOST (default: localhost)
    PG_PORT (default: 5432)
    PG_DB   (default: postgres)
    PG_USER (default: postgres)
    PG_PASSWORD (default: <üres>)
    SLOT_AUTOHEAL_DRY_RUN (default: 0)  -> 1 = csak log, nem ír
    SLOT_AUTOHEAL_STALE_WAL_SECONDS (default: 300)
"""

import os
import sys
import json
import time
import logging
import datetime as dt
from dataclasses import dataclass, field, asdict
from typing import List, Optional, Dict, Any

try:
    import psycopg2
    from psycopg2.extras import RealDictCursor
except ImportError:
    print("ERROR: psycopg2 nincs telepítve. Telepítsd: pip install psycopg2-binary", file=sys.stderr)
    sys.exit(2)

# --------------------------------------------------------------------------- #
# Konfiguráció
# --------------------------------------------------------------------------- #

EXPECTED_SLOTS = ["runa_replica", "nova_replica"]

PG_HOST = os.environ.get("PG_HOST", "localhost")
PG_PORT = int(os.environ.get("PG_PORT", "5432"))
PG_DB = os.environ.get("PG_DB", "postgres")
PG_USER = os.environ.get("PG_USER", "postgres")
PG_PASSWORD = os.environ.get("PG_PASSWORD", "")

DRY_RUN = os.environ.get("SLOT_AUTOHEAL_DRY_RUN", "0") == "1"
STALE_WAL_SECONDS = int(os.environ.get("SLOT_AUTOHEAL_STALE_WAL_SECONDS", "300"))

LOG_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "logs")
LOG_PATH = os.path.join(LOG_DIR, "pg_replica_slot_autoheal.log")
STATE_PATH = os.path.join(LOG_DIR, "pg_replica_slot_autoheal_state.json")

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
    handlers=[
        logging.StreamHandler(sys.stdout),
    ],
)
log = logging.getLogger("pg_replica_slot_autoheal")


# --------------------------------------------------------------------------- #
# Adatstruktúrák
# --------------------------------------------------------------------------- #

@dataclass
class SlotInfo:
    slot_name: str
    slot_type: str
    active: bool
    restart_lsn: Optional[str]
    confirmed_flush_lsn: Optional[str]
    wal_status: Optional[str]
    xmin: Optional[int]

    @classmethod
    def from_row(cls, row: Dict[str, Any]) -> "SlotInfo":
        return cls(
            slot_name=row.get("slot_name"),
            slot_type=row.get("slot_type"),
            active=bool(row.get("active")),
            restart_lsn=row.get("restart_lsn"),
            confirmed_flush_lsn=row.get("confirmed_flush_lsn"),
            wal_status=row.get("wal_status"),
            xmin=row.get("xmin"),
        )


@dataclass
class HealAction:
    slot_name: str
    action: str  # "created" | "recreated" | "advanced" | "noop" | "alert_stale"
    detail: str
    timestamp: str = field(default_factory=lambda: dt.datetime.utcnow().isoformat() + "Z")


@dataclass
class HealReport:
    run_id: str
    timestamp: str
    expected_slots: List[str]
    found_slots: List[str]
    missing_slots: List[str]
    stale_slots: List[str]
    actions: List[HealAction]
    dry_run: bool
    healthy: bool

    def to_dict(self) -> Dict[str, Any]:
        return {
            "run_id": self.run_id,
            "timestamp": self.timestamp,
            "expected_slots": self.expected_slots,
            "found_slots": self.found_slots,
            "missing_slots": self.missing_slots,
            "stale_slots": self.stale_slots,
            "actions": [asdict(a) for a in self.actions],
            "dry_run": self.dry_run,
            "healthy": self.healthy,
        }


# --------------------------------------------------------------------------- #
# Állapot-persistencia (WAL stagnálás detektáláshoz)
# --------------------------------------------------------------------------- #

def _ensure_dirs() -> None:
    os.makedirs(LOG_DIR, exist_ok=True)


def load_state() -> Dict[str, Any]:
    _ensure_dirs()
    if not os.path.exists(STATE_PATH):
        return {"slots": {}}
    try:
        with open(STATE_PATH, "r", encoding="utf-8") as f:
            return json.load(f)
    except (json.JSONDecodeError, OSError):
        return {"slots": {}}


def save_state(state: Dict[str, Any]) -> None:
    _ensure_dirs()
    tmp = STATE_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(state, f, indent=2, default=str)
    os.replace(tmp, STATE_PATH)


# --------------------------------------------------------------------------- #
# DB műveletek
# --------------------------------------------------------------------------- #

def connect():
    return psycopg2.connect(
        host=PG_HOST,
        port=PG_PORT,
        dbname=PG_DB,
        user=PG_USER,
        password=PG_PASSWORD,
    )


def fetch_slots(conn) -> List[SlotInfo]:
    sql = """
        SELECT slot_name, slot_type, active,
               restart_lsn::text AS restart_lsn,
               confirmed_flush_lsn::text AS confirmed_flush_lsn,
               wal_status, xmin::text AS xmin
        FROM pg_replication_slots
        ORDER BY slot_name;
    """
    with conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(sql)
        rows = cur.fetchall()
    return [SlotInfo.from_row(r) for r in rows]


def slot_exists(conn, slot_name: str) -> bool:
    with conn.cursor() as cur:
        cur.execute("SELECT 1 FROM pg_replication_slots WHERE slot_name = %s", (slot_name,))
        return cur.fetchone() is not None


def create_logical_slot(conn, slot_name: str, plugin: str = "pgoutput") -> None:
    with conn.cursor() as cur:
        cur.execute(
            "SELECT pg_create_logical_replication_slot(%s, %s);",
            (slot_name, plugin),
        )
    conn.commit()
    log.info("Created logical slot %s (plugin=%s)", slot_name, plugin)


def drop_slot(conn, slot_name: str) -> None:
    with conn.cursor() as cur:
        cur.execute("SELECT pg_drop_replication_slot(%s);", (slot_name,))
    conn.commit()
    log.warning("Dropped stale/damaged slot %s", slot_name)


def current_lsn(conn) -> str:
    with conn.cursor() as cur:
        cur.execute("SELECT pg_current_wal_lsn()::text;")
        return cur.fetchone()[0]


# --------------------------------------------------------------------------- #
# WAL stagnálás detektálás
# --------------------------------------------------------------------------- #

def lsn_to_int(lsn: str) -> int:
    """PG LSN '0/16B3748' -> int."""
    if not lsn:
        return 0
    try:
        hi, lo = lsn.split("/")
        return (int(hi, 16) << 32) + int(lo, 16)
    except (ValueError, AttributeError):
        return 0


def detect_stale_slots(
    slots: List[SlotInfo], state: Dict[str, Any], stale_seconds: int
) -> List[str]:
    now_ts = time.time()
    stale: List[str] = []
    for s in slots:
        if s.slot_name not in EXPECTED_SLOTS:
            continue
        if not s.restart_lsn:
            continue
        prev = state.get("slots", {}).get(s.slot_name, {})
        prev_lsn = prev.get("restart_lsn")
        prev_ts = prev.get("ts", 0)
        if prev_lsn and prev_ts:
            if lsn_to_int(s.restart_lsn) == lsn_to_int(prev_lsn):
                delta = now_ts - prev_ts
                if delta >= stale_seconds:
                    stale.append(s.slot_name)
    return stale


def update_state(slots: List[SlotInfo], state: Dict[str, Any]) -> None:
    now_ts = time.time()
    slots_state = state.setdefault("slots", {})
    for s in slots:
        if s.slot_name not in EXPECTED_SLOTS:
            continue
        slots_state[s.slot_name] = {
            "restart_lsn": s.restart_lsn,
            "confirmed_flush_lsn": s.confirmed_flush_lsn,
            "active": s.active,
            "ts": now_ts,
        }


# --------------------------------------------------------------------------- #
# Auto-heal logika
# --------------------------------------------------------------------------- #

def autoheal(dry_run: bool = DRY_RUN) -> HealReport:
    run_id = f"heal_{int(time.time()*1000)}"
    report_ts = dt.datetime.utcnow().isoformat() + "Z"
    actions: List[HealAction] = []

    state = load_state()
    conn = connect()
    try:
        cur_lsn = current_lsn(conn)
        log.info("Current WAL LSN: %s", cur_lsn)

        slots = fetch_slots(conn)
        found_names = [s.slot_name for s in slots]
        missing = [name for name in EXPECTED_SLOTS if name not in found_names]

        # 1) Hiányzó slotok auto-create
        for name in missing:
            if dry_run:
                actions.append(HealAction(name, "created", f"[dry-run] would create logical slot {name}"))
                log.info("[dry-run] would create slot %s", name)
                continue
            try:
                if slot_exists(conn, name):
                    drop_slot(conn, name)
                    actions.append(HealAction(name, "recreated", f"slot existed in bad state, dropped+recreated"))
                else:
                    create_logical_slot(conn, name)
                    actions.append(HealAction(name, "created", f"logical slot {name} created with pgoutput"))
            except Exception as exc:
                log.error("Failed to (re)create slot %s: %s", name, exc)
                actions.append(HealAction(name, "noop", f"create failed: {exc}"))

        # 2) Friss slot lista a create után
        slots = fetch_slots(conn)
        found_names = [s.slot_name for s in slots]

        # 3) WAL stagnálás detektálás
        stale = detect_stale_slots(slots, state, STALE_WAL_SECONDS)

        # 4) Stale slotok kezelése: drop + recreate (ha nem dry-run)
        for name in stale:
            if dry_run:
                actions.append(HealAction(name, "alert_stale", f"[dry-run] slot {name} WAL stagnant >= {STALE_WAL_SECONDS}s"))
                continue
            try:
                drop_slot(conn, name)
                create_logical_slot(conn, name)
                actions.append(HealAction(name, "recreated", f"stale WAL (restart_lsn unchanged >= {STALE_WAL_SECONDS}s) -> dropped+recreated"))
                log.warning("Slot %s was stale, recreated", name)
            except Exception as exc:
                log.error("Failed to recreate stale slot %s: %s", name, exc)
                actions.append(HealAction(name, "noop", f"stale recreate failed: {exc}"))

        # 5) Állapot mentése a következő futáshoz
        slots = fetch_slots(conn)
        update_state(slots, state)
        state["last_run"] = report_ts
        save_state(state)

        # 6) Inaktív (de létező) slotok -> alert (nem töröljük, mert a replica lehet, hogy reconnectel)
        for s in slots:
            if s.slot_name in EXPECTED_SLOTS and not s.active:
                actions.append(HealAction(
                    s.slot_name, "alert_stale",
                    f"slot exists but inactive (restart_lsn={s.restart_lsn}, wal_status={s.wal_status})"
                ))
                log.warning("Slot %s inactive (wal_status=%s)", s.slot_name, s.wal_status)

        # 7) Egészségértékelés
        final_found = [s.slot_name for s in slots if s.slot_name in EXPECTED_SLOTS]
        all_present = all(name in final_found for name in EXPECTED_SLOTS)
        no_stale = len(stale) == 0
        healthy = all_present and no_stale

        return HealReport(
            run_id=run_id,
            timestamp=report_ts,
            expected_slots=list(EXPECTED_SLOTS),
            found_slots=final_found,
            missing_slots=[n for n in EXPECTED_SLOTS if n not in final_found],
            stale_slots=stale,
            actions=actions,
            dry_run=dry_run,
            healthy=healthy,
        )
    finally:
        conn.close()


def write_report_json(report: HealReport) -> str:
    _ensure_dirs()
    path = os.path.join(LOG_DIR, "pg_replica_slot_autoheal_last_report.json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(report.to_dict(), f, indent=2)
    return path


# --------------------------------------------------------------------------- #
# Main
# --------------------------------------------------------------------------- #

def main() -> int:
    log.info("=== PG replica slot auto-heal start ===")
    log.info("Expected slots: %s | dry_run=%s | stale_threshold=%ds",
             EXPECTED_SLOTS, DRY_RUN, STALE_WAL_SECONDS)

    try:
        report = autoheal(dry_run=DRY_RUN)
    except Exception as exc:
        log.exception("Auto-heal failed: %s", exc)
        return 3

    path = write_report_json(report)
    log.info("Report written: %s", path)

    print(json.dumps(report.to_dict(), indent=2))

    if report.healthy:
        log.info("=== Auto-heal OK: all expected slots present, no stale WAL ===")
        return 0
    else:
        log.warning("=== Auto-heal completed but not fully healthy (missing=%s stale=%s) ===",
                    report.missing_slots, report.stale_slots)
        return 1


if __name__ == "__main__":
    sys.exit(main())